            "\"children\":%u,\"childbytes\":%llu,\"parents\":%u,"
            "\"end\":%llu,\"rbytes\":%llu,\"wbytes\":%llu,"
            "\"held\":%d,\"readbusy\":%d,\"preparebusy\":%d,\"quiet\":%d,"
            "\"V_rbytes\":%llu,\"V_wbytes\":%llu,"
            "\"a_job_done\":%d,"
            "\"ptw_ar_transactions\":%llu,\"ptw_active_cycles\":%llu,"
            "\"full_accepted\":%d}\n",
            phase, (unsigned)pause_mode, natural_first.c_str(), g_cycle,
            pause_request_cycle, pause_seal_cycle, pause_first_quiet_cycle,
            pause_end_cycle,
            (pause_request_cycle >= 0) ? (g_cycle - pause_request_cycle) : -1L,
            s.offers, s.wlast, s.pendb,
            s.children, (unsigned long long)s.childbytes, s.parents,
            (unsigned long long)s.end, (unsigned long long)s.rbytes,
            (unsigned long long)s.wbytes,
            (int)s.held, (int)s.readbusy, (int)s.preparebusy, (int)s.quiet,
            (unsigned long long)s.v_rbytes, (unsigned long long)s.v_wbytes,
            (int)s.a_done,
            (unsigned long long)s.ptw_ar_transactions,
            (unsigned long long)s.ptw_active_cycles,
            (int)full_accepted);
    }
